use crate::Lexer;
use destack_ast::{LiteralType, NumberBase, Token, TokenType, render_tokens};
use destack_source::{FileId, LanguageOptions};

/// Assert that the tokens generated by `tokenize` match the expected tokens.
macro_rules! assert_tokenize_eq_roundtrip {
    ($src:expr, $($expected:expr),* $(,)?) => {
        let file_id = FileId::new(0);
        // tokenize
        let language = LanguageOptions::default();
        let (tokens, _) = Lexer::lex(file_id, $src, language);
        let tokens: Vec<Token> = tokens.into_iter().map(|token| token.token).collect();
        // must match the expected tokens
        let mut expected_tokens = vec![$($expected),*];
        // ensure the last token is an EOF token
        if !matches!(expected_tokens.last(), Some(token) if token.ty == TokenType::End) {
            expected_tokens.push(Token::end());
        }
        assert_eq!(tokens, expected_tokens);
        // render back to input string
        let rendered_input = render_tokens(&tokens, $src);
        assert_eq!(rendered_input, $src);
        // re-tokenize on the rendered input
        let (tokens_again, _) = Lexer::lex(file_id, &rendered_input, language);
        let tokens_again: Vec<Token> = tokens_again.into_iter().map(|token| token.token).collect();
        assert_eq!(tokens_again, tokens);
    };
}

// Raw strings (r"...", r#"..."#) have been removed from the language

#[test]
fn test_lex_valid_weird_unicode() {
    assert_tokenize_eq_roundtrip!(
        "\u{3}\n",
        Token::new(TokenType::Unknown, 1, None),
        Token::new(TokenType::Newline, 1, None),
    );
}

#[test]
fn test_lex_random_symbols() {
    assert_tokenize_eq_roundtrip!(
        "a..b => c->d x _ : ? ! @ ~",
        // a
        Token::new(TokenType::Identifier, 1, None),
        // ..
        Token::new(TokenType::Range, 2, None),
        // b
        Token::new(TokenType::Identifier, 1, None),
        // (space)
        Token::new(TokenType::Whitespace, 1, None),
        // =>
        Token::new(TokenType::ArrowWide, 2, None),
        // (space)
        Token::new(TokenType::Whitespace, 1, None),
        // c
        Token::new(TokenType::Identifier, 1, None),
        // ->
        Token::new(TokenType::Arrow, 2, None),
        // d
        Token::new(TokenType::Identifier, 1, None),
        // (space)
        Token::new(TokenType::Whitespace, 1, None),
        // x
        Token::new(TokenType::Identifier, 1, None),
        // (space)
        Token::new(TokenType::Whitespace, 1, None),
        // _
        Token::new(TokenType::Wildcard, 1, None),
        // (space)
        Token::new(TokenType::Whitespace, 1, None),
        // :
        Token::new(TokenType::Colon, 1, None),
        // (space)
        Token::new(TokenType::Whitespace, 1, None),
        // ?
        Token::new(TokenType::Maybe, 1, None),
        // (space)
        Token::new(TokenType::Whitespace, 1, None),
        // !
        Token::new(TokenType::Not, 1, None),
        // (space)
        Token::new(TokenType::Whitespace, 1, None),
        // @
        Token::new(TokenType::At, 1, None),
        // (space)
        Token::new(TokenType::Whitespace, 1, None),
        // ~
        Token::new(TokenType::ElementwiseNot, 1, None),
    );
}

#[test]
fn test_lex_comparisons_and_equals() {
    assert_tokenize_eq_roundtrip!(
        "a==b != c <= d >= e < f > g",
        Token::new(TokenType::Identifier, 1, None),
        Token::new(TokenType::Equal, 2, None),
        Token::new(TokenType::Identifier, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::NotEqual, 2, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::Identifier, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::LessThanOrEqual, 2, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::Identifier, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::GreaterThanOrEqual, 2, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::Identifier, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::LessThan, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::Identifier, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::GreaterThan, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::Identifier, 1, None),
    );
}

#[test]
fn test_lex_smoke() {
    assert_tokenize_eq_roundtrip!(
        "fn main() { println!(\"zebra\"); }\n",
        Token::new(TokenType::Identifier, 2, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::Identifier, 4, None),
        Token::new(TokenType::OpenParenthesis, 1, None),
        Token::new(TokenType::CloseParenthesis, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::OpenBrace, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::Identifier, 7, None),
        Token::new(TokenType::Not, 1, None),
        Token::new(TokenType::OpenParenthesis, 1, None),
        Token::new(
            TokenType::Literal,
            7,
            Some(LiteralType::String {
                is_terminated: true,
                has_invalid_escape: false,
            })
        ),
        Token::new(TokenType::CloseParenthesis, 1, None),
        Token::new(TokenType::Semicolon, 1, None),
        Token::new(TokenType::Whitespace, 1, None),
        Token::new(TokenType::CloseBrace, 1, None),
        Token::new(TokenType::Newline, 1, None),
    );
}

