#[test]
fn test_lex_literals() {
    assert_tokenize_eq_roundtrip!(
        r####"
true
false
'a'
"a"
1234
0b101
0xABC
1.0
1.0e10
2n
0xABn
0b101n
0o77n
"####,
        Token::new(TokenType::Newline, 1, None),
        // true
        Token::new(
            TokenType::Literal,
            4,
            Some(LiteralType::Boolean { value: true })
        ),
        Token::new(TokenType::Newline, 1, None),
        // false
        Token::new(
            TokenType::Literal,
            5,
            Some(LiteralType::Boolean { value: false })
        ),
        Token::new(TokenType::Newline, 1, None),
        // 'a'
        Token::new(
            TokenType::Literal,
            3,
            Some(LiteralType::Character {
                is_terminated: true,
                is_html_entity: false,
            })
        ),
        Token::new(TokenType::Newline, 1, None),
        // "a"
        Token::new(
            TokenType::Literal,
            3,
            Some(LiteralType::String {
                is_terminated: true,
                has_invalid_escape: false,
            })
        ),
        Token::new(TokenType::Newline, 1, None),
        // 1234
        Token::new(
            TokenType::Literal,
            4,
            Some(LiteralType::Int {
                base: NumberBase::Decimal,
                is_empty: false,
                is_bigint: false,
            })
        ),
        // 0b101
        Token::new(TokenType::Newline, 1, None),
        Token::new(
            TokenType::Literal,
            5,
            Some(LiteralType::Int {
                base: NumberBase::Binary,
                is_empty: false,
                is_bigint: false,
            })
        ),
        Token::new(TokenType::Newline, 1, None),
        // 0xABC
        Token::new(
            TokenType::Literal,
            5,
            Some(LiteralType::Int {
                base: NumberBase::Hexadecimal,
                is_empty: false,
                is_bigint: false,
            })
        ),
        Token::new(TokenType::Newline, 1, None),
        // 1.0
        Token::new(
            TokenType::Literal,
            3,
            Some(LiteralType::Float {
                base: NumberBase::Decimal,
                is_empty_exponent: false
            })
        ),
        Token::new(TokenType::Newline, 1, None),
        // 1.0e10
        Token::new(
            TokenType::Literal,
            6,
            Some(LiteralType::Float {
                base: NumberBase::Decimal,
                is_empty_exponent: false
            })
        ),
        Token::new(TokenType::Newline, 1, None),
        // 2n
        Token::new(
            TokenType::Literal,
            2,
            Some(LiteralType::Int {
                base: NumberBase::Decimal,
                is_empty: false,
                is_bigint: true,
            })
        ),
        Token::new(TokenType::Newline, 1, None),
        // 0xABn
        Token::new(
            TokenType::Literal,
            5,
            Some(LiteralType::Int {
                base: NumberBase::Hexadecimal,
                is_empty: false,
                is_bigint: true,
            })
        ),
        Token::new(TokenType::Newline, 1, None),
        // 0b101n
        Token::new(
            TokenType::Literal,
            6,
            Some(LiteralType::Int {
                base: NumberBase::Binary,
                is_empty: false,
                is_bigint: true,
            })
        ),
        Token::new(TokenType::Newline, 1, None),
        // 0o77n
        Token::new(
            TokenType::Literal,
            5,
            Some(LiteralType::Int {
                base: NumberBase::Octal,
                is_empty: false,
                is_bigint: true,
            })
        ),
        Token::new(TokenType::Newline, 1, None),
    );
}

